/* UX-U1 authored design source. In-memory simulation only; no application imports,
   network writes, persistent storage, uploads or provider calls. */
"use strict";
const stages = ["brief", "suppliers", "quotes", "comparison", "decision"];
const names = {dashboard:"Your sourcing projects",brief:"Shape your sourcing brief",suppliers:"Review supplier fit",quotes:"Review your quotes",comparison:"Compare the facts",decision:"Record your preference"};
const suppliers = [
  {id:"harbor",name:"Harbor Pouch Works",country:"Vietnam",initials:"HP",moq:"500",lead:"25 days",price:"USD 4.22",material:"Meets",certification:"Unknown",branding:"Meets"},
  {id:"cedar",name:"Cedar Textile Studio",country:"Portugal",initials:"CT",moq:"1,000",lead:"38 days",price:"USD 3.95",material:"Meets",certification:"Meets",branding:"Conflict"},
  {id:"moss",name:"Moss Packaging Co.",country:"China",initials:"MP",moq:"300",lead:"21 days",price:"USD 4.50",material:"Does not meet",certification:"Unknown",branding:"Meets"}
];
const groups = {
  Commercial:[["quantity","Quoted quantity"],["price","Unit price"],["currency","Original currency"],["moq","Minimum order quantity"],["sample","Sample cost"],["tooling","Tooling or setup cost"],["packaging","Packaging cost"],["shipping","Shipping cost"]],
  Timeline:[["sampleLead","Sample lead time"],["production","Production lead time"],["shippingTime","Shipping time"],["totalLead","Total stated lead time"]],
  Terms:[["payment","Payment terms"],["incoterm","Incoterm"],["validity","Quote validity"],["warranty","Warranty"]],
  Compliance:[["certifications","Certifications"],["compliance","Compliance notes"]],
  Other:[["exclusions","Exclusions"],["conditions","Special conditions"],["supplierNotes","Supplier notes"],["notes","Your quote notes"]]
};
const clone = value => JSON.parse(JSON.stringify(value));
const h = value => String(value ?? "").replace(/[&<>"']/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const title = value => value[0].toUpperCase()+value.slice(1);
const blankQuote = () => Object.fromEntries(Object.values(groups).flat().map(([key])=>[key,""]));
let sourceQuotes, saved, draft, state, pending, errors, remote, mode = "success", generation = 0, lastFocus, departureTimer;
let view = "dashboard", scenario = "normal", renderedView="dashboard", renderedSupplier="harbor";
const disclosures=new Map();
const app = document.getElementById("app"), modal = document.getElementById("modal");
function reset() {
  generation++;
  saved = {
    brief:{product:"Recycled cosmetic travel bag",category:"Bags & accessories",quantity:"2000",target:"5.00",destination:"Sydney, Australia",deliveryType:"Period",delivery:"November 2027",requirements:[{id:"material",kind:"Material",value:"Recycled polyester",importance:"Required"},{id:"branding",kind:"Custom branding",value:"Printed logo",importance:"Required"},{id:"certification",kind:"Certification",value:"GRS certification",importance:"Preferred"}],context:"Neutral colors; recyclable packaging preferred."},
    harbor:{...blankQuote(),quantity:"2000",price:"4.22",currency:"USD",moq:"500",sample:"45.00",tooling:"220.00",packaging:"0.00",production:"25 days",payment:"30% deposit, 70% before shipment",incoterm:"FOB",validity:"30 days",compliance:"GRS evidence not provided",conditions:"Delivery date to be agreed"},
    cedar:{...blankQuote(),quantity:"5000",price:"3.95",currency:"USD",moq:"1000",tooling:"150.00",shipping:"650.00",production:"38 days",certifications:"GRS",payment:"50% deposit",conditions:"Branding specifications differ between catalog and quote"},
    moss:blankQuote(),
    "notes-harbor":{notes:""},"notes-cedar":{notes:""},"notes-moss":{notes:""},
    decision:{selection:"",notes:""},project:{name:"Recycled travel bags"}
  };
  sourceQuotes = clone({harbor:saved.harbor,cedar:saved.cedar,moss:{...saved.harbor,price:"4.50",moq:"300",production:"21 days"}});
  draft = clone(saved); pending = {}; errors = {}; remote = {};
  state = {comparisonSnapshot:clone(saved),comparisonSuppliers:["harbor","cedar"],briefEditing:false,briefApproved:true,shortlistApproved:true,selected:["harbor","cedar","moss"],quoteStatus:{harbor:"Confirmed",cedar:"Confirmed",moss:"Not added"},quoteEdit:{},entry:{},supplier:"harbor",comparison:true,stale:false,suppliersStale:false,preference:null,ai:true,aiPending:false,createOpen:false,departure:false,feedback:"",evidenceField:"price",evidenceSupplier:"harbor",membershipPending:false};
}
function dirty(key) { return JSON.stringify(draft[key]) !== JSON.stringify(saved[key]); }
function dirtyKeys() { return Object.keys(draft).filter(dirty); }
function recordLabel(key) { const supplier=suppliers.find(s=>s.id===key);return key==="membership"?"Shortlist membership":key.startsWith("notes-") ? `${suppliers.find(s=>s.id===key.slice(6))?.name} notes` : supplier?`${supplier.name} quote`:title(key); }
function announce(message) { document.getElementById("announcement").textContent = message; }
function badge(text) { const tone = /fail|not meet|Conflict/i.test(text)?"red":/Unknown|review|stale|Unsaved|not saved|Outdated|pending/i.test(text)?"amber":/Not added|Optional|Not provided/i.test(text)?"gray":"";return `<span class="badge ${tone}">${h(text)}</span>`; }
function button(label,action,cls="",extra="") { return `<button type="button" class="${cls}" data-action="${action}" ${extra}>${label}</button>`; }
function status(key) { return remote[key]?"Saved elsewhere — review changes":errors[key]||pending[key]?errors[key]||"Saving…":dirty(key)?"Unsaved changes":"All changes saved"; }
function footer(key,label="Save changes",extra="") { return `<div class="record-footer"><span class="save-status ${errors[key]?"error":""}" data-status="${key}" data-dirty="${dirty(key)}">${h(status(key))}</span><div class="actions">${button("Discard edits","discard","tertiary",`data-record="${key}"`)}${button(label,"save","",`data-record="${key}" ${pending[key]||remote[key]?"disabled":""}`)}${extra}</div></div>`; }
function input(key,field,label,opts={}) { const val=draft[key][field]??"";return `<label ${opts.wide?'class="wide"':""}>${label}<${opts.area?"textarea":"input"} aria-label="${h(label.replace(/<[^>]*>/g,""))}" data-record="${key}" data-field="${field}" ${opts.area?'rows="3"':`type="text" value="${h(val)}"`} ${opts.numeric?'inputmode="decimal"':""}>${opts.area?h(val)+"</textarea>":""}${opts.hint?`<span class="hint">${opts.hint}</span>`:""}</label>`; }
function demoNotice(){return `<div class="demo-notice"><span class="badge gray">Demo dataset</span><p>Demo suppliers use a curated synthetic dataset. SourcePilot does not perform live supplier research.</p></div>`;}
function next(){
  if(!state.briefApproved)return ["brief","Review and approve your saved brief","Review Brief"];
  if(state.suppliersStale)return ["suppliers","Your requirements changed. Refresh supplier evaluations.","Refresh suppliers"];
  if(!state.shortlistApproved)return ["suppliers","Review and approve your saved shortlist","Review shortlist"];
  const count=state.selected.filter(id=>state.quoteStatus[id]==="Confirmed").length;
  if(count<2)return ["quotes","Confirm quotes from two shortlisted suppliers to compare","Review quotes"];
  if(!state.comparison||state.stale)return ["comparison",state.stale?"Your comparison is outdated. Refresh it using saved values.":"Your confirmed quotes are ready to compare",state.stale?"Refresh comparison":"Generate comparison"];
  return ["decision",state.preference?"Your preference is saved. You can change it at any time.":"Review the facts and record your preferred supplier",state.preference?"Manage preference":"Record preference"];
}
function heading(sub,statusText=""){return `<div class="stage-heading"><div><h1 id="stage-title" tabindex="-1">${names[view]}</h1><p class="context-label">${view==="dashboard"?"Sourcing workspace":`Viewing ${title(view)} · ${stages.indexOf(view)+1} of 5`}</p><p>${sub}</p></div>${statusText?badge(statusText):""}</div>`;}
function notice(kind,text,action="",label=""){return `<div class="notice ${kind}"><strong>${text}</strong>${action?`<div class="actions">${button(label,action,"secondary")}</div>`:""}</div>`;}
function conflictNotice(key){return remote[key]?`<div class="notice inline-conflict"><strong>This record changed elsewhere.</strong><p>Your draft is preserved. Review both complete records before saving; related values will not be combined automatically.</p>${button("Review saved and draft values","conflict","secondary",`data-record="${key}"`)}</div>`:"";}
function recordSummary(key,value){
  const row=(label,text)=>`<div><span>${h(label)}</span><strong>${h(text||"Not provided")}</strong></div>`;
  if(key==="brief")return `<div class="review-summary">${[["Product",value.product],["Category",value.category],["Quantity",value.quantity],["Target unit price",value.target],["Destination",value.destination],["Delivery",value.delivery],["Additional context",value.context]].map(([l,v])=>row(l,v)).join("")}${value.requirements.map(r=>row(`${r.kind} · ${r.importance}`,r.value)).join("")}</div>`;
  if(suppliers.some(s=>s.id===key))return `<div class="review-summary">${row("Unit price and currency",`${value.currency||"Unknown currency"} ${value.price||"Unknown amount"}`)}${Object.values(groups).flat().filter(([f])=>!["price","currency"].includes(f)).map(([field,label])=>row(label,value[field])).join("")}</div>`;
  return `<div class="review-summary">${row("Notes",value.notes)}</div>`;
}
function loading(){return `<div class="card loading-card" role="status"><h2>Loading ${view==="dashboard"?"projects":title(view).toLowerCase()}…</h2><p class="muted">Your drafts stay in this workspace while we check saved information.</p><div class="skeleton"></div><div class="skeleton large"></div>${button("Finish simulated load","recover","secondary")}</div>`;}
function commonState(){
  if(scenario==="loading")return loading();
  if(scenario==="blocked"&&!["dashboard","brief","decision"].includes(view))return notice("info","Approve the current Brief and shortlist before continuing here.","go-brief","Review Brief")+`<div class="card"><h2>Your saved work is retained</h2><p class="muted">You can still visit every stage. Unavailable actions explain what needs attention.</p></div>`;
  return "";
}
function dashboard(){return `${heading("A clear path from your sourcing request to a considered supplier decision.")}<div class="actions" style="margin-bottom:24px">${button("+ New project","create")}</div>${scenario==="loading"?loading():scenario==="failed"?notice("danger","Projects could not be loaded. Your projects have not been deleted.","recover","Try again"):scenario==="empty"?`<div class="card empty"><div class="empty-icon" aria-hidden="true">＋</div><h2>Start with what you need to source</h2><p>Describe your product, quantity and delivery needs. You will review the brief before moving on to suppliers.</p>${button("Create your first project","create")}</div>`:`<div class="card" style="padding:0"><div class="project-row"><div><a href="?stage=brief" data-nav="brief">${h(saved.project.name)}</a><p>Recycled polyester · 2,000 units · Sydney</p></div><div>${badge(state.stale?"Comparison outdated":state.preference?"Preference saved":"Ready for a decision")}<p>Next: ${h(next()[2])}</p></div><div class="project-counts"><strong class="small">${state.selected.length} shortlisted · ${state.selected.filter(id=>state.quoteStatus[id]==="Confirmed").length} confirmed</strong><p>Preferred: ${state.preference?suppliers.find(s=>s.id===state.preference).name:"No decision yet"}</p><p>Updated today · simulated</p></div>${button("Open project →","open-project","secondary")}</div></div>`}${demoNotice()}<p class="page-foot">Your sourcing decisions stay yours. SourcePilot does not contact suppliers or place orders.</p>`;}
function brief(){
  if(state.briefApproved&&!state.briefEditing&&!dirty("brief")&&!remote.brief&&!["loading","failed","blocked"].includes(scenario))return heading("Your saved sourcing requirements.","Approved")+`<section class="card brief-saved"><div class="card-head"><h2>Approved Brief</h2>${button("Edit Brief","edit-brief","secondary")}</div>${recordSummary("brief",saved.brief)}<p class="issue-copy">Target currency is unknown. Optional omissions do not block approval.</p><details class="disclosure"><summary>Original sourcing request</summary><p>We need 2,000 recycled cosmetic travel bags with our logo. Target below $5 each, delivered to Sydney in November. Prefer GRS certification.</p></details></section>`;
  return heading("Turn your request into a brief you can confidently approve.",state.briefApproved?"Approved":scenario==="blocked"?"In progress":"Ready for review")+commonState()+ (scenario==="loading"?"":`${scenario==="failed"?notice("danger","The request could not be analyzed. Your entries are safe; continue manually or retry.","recover","Retry analysis"):""}${scenario==="blocked"?notice("","Delivery destination is required before this Brief can be approved."):""}${conflictNotice("brief")}<div class="stack"><form data-form="brief" class="card"><div class="card-head"><div><h2>Product and quantity</h2><p>Start with the essentials. Save before reviewing approval.</p></div>${badge("Your editable brief")}</div><div class="fields">${input("brief","product","Product name")}${input("brief","category","Category")}${input("brief","quantity","Requested quantity",{numeric:true})}${input("brief","target","Target unit price <span class='muted'>(optional)</span>",{numeric:true,hint:"An optional target, not a quoted supplier price."})}</div><details class="disclosure"><summary>Original sourcing request</summary><div><p class="small">We need 2,000 recycled cosmetic travel bags with our logo. Target below $5 each, delivered to Sydney in November. Prefer GRS certification.</p><p class="issue-copy">Currency was not specified for the target. This uncertainty is retained.</p></div></details></form><section class="card"><h2>Commercial and delivery</h2><div class="fields" style="margin-top:18px">${input("brief","destination","Destination")}${input("brief","delivery","Delivery period",{hint:"An exact date or a stated period is acceptable."})}</div></section><section class="card"><div class="card-head"><div><h2>Requirements and importance</h2><p>Required findings stay visible even when a supplier falls short.</p></div></div>${draft.brief.requirements.map(r=>`<div class="requirement"><div class="requirement-head"><h3>${h(r.kind)}</h3>${button("Remove","remove-requirement","tertiary",`data-id="${r.id}" aria-label="Remove ${h(r.kind)} requirement"`)}</div><div class="fields"><label>Expected ${h(r.kind.toLowerCase())}<input data-requirement="${r.id}" data-part="value" value="${h(r.value)}"></label><label>Importance<select data-requirement="${r.id}" data-part="importance">${["Required","Preferred","Informational"].map(i=>`<option ${r.importance===i?"selected":""}>${i}</option>`).join("")}</select></label></div></div>`).join("")}${button("+ Add requirement","add-requirement","secondary")}</section><section class="card"><details><summary>Additional context <span class="muted small">Optional</span></summary><div style="padding-top:16px">${input("brief","context","Notes and informational attributes",{area:true})}</div></details><p class="issue-copy">Target currency is unknown. Optional omissions do not block approval.</p>${footer("brief","Save Brief",button("Review saved Brief","review-brief","secondary",`${dirty("brief")||pending.brief||remote.brief?"disabled":""}`))}</section></div>`);
}
function supplierFindings(s){return `<div><div class="finding"><span>Recycled material<small>Required</small></span>${badge(s.material)}</div><div class="finding"><span>Custom branding<small>Required</small></span>${badge(s.branding)}</div><div class="finding"><span>GRS certification<small>Preferred</small></span>${badge(s.certification)}</div></div>`;}
function supplierView(){
  const common=commonState(); if(common)return heading("Review the evidence, then choose who moves forward.")+common;
  return heading("A focused shortlist, with the strengths and gaps in plain sight.",state.shortlistApproved?"Shortlist approved":"Needs review")+`${scenario==="failed"?notice("danger","Supplier discovery failed. Your existing shortlist is retained.","recover","Retry discovery"):""}${state.suppliersStale?notice("","Supplier evaluations are outdated after a Brief change.","refresh-suppliers","Refresh evaluations"):""}<div class="card shortlist-strip" style="margin-bottom:20px"><div><h2>${state.selected.length} suppliers shortlisted</h2><p class="small muted">Approve up to 3. Two confirmed quotes will enable comparison.</p></div>${button("Review shortlist","review-shortlist","",`${state.membershipPending||state.suppliersStale?"disabled":""}`)}</div>${scenario==="empty"?`<div class="card empty"><h2>No matching candidates yet</h2><p>Review your product category and requirements, then search the curated dataset again.</p><div class="actions" style="justify-content:center">${button("Review Brief","go-brief","secondary")}${button("Discover suppliers","recover")}</div></div>`:`<div class="grid-two">${suppliers.map(s=>`<article class="card supplier-card"><div><p class="context-label">${h(s.country)} · Curated supplier</p><h3>${h(s.name)}</h3><p class="country">Small-batch travel accessories and custom pouches</p></div><dl class="facts"><div><dt>Minimum order</dt><dd>${s.moq} units</dd></div><div><dt>Typical lead time</dt><dd>${s.lead}</dd></div><div><dt>Indicative unit price</dt><dd>${s.price}</dd></div><div><dt>Shortlist</dt><dd>${state.selected.includes(s.id)?"Selected":"Not selected"}</dd></div></dl>${supplierFindings(s)}${s.branding==="Conflict"?`<p class="issue-copy">Conflict: catalog and quote describe different branding capabilities.</p>`:s.material==="Does not meet"?`<p class="issue-copy">Required material fails: the listed material is virgin polyester.</p>`:`<p class="small muted">Unknown certification means evidence is missing, not that certification failed.</p>`}<div class="actions">${button(state.selected.includes(s.id)?"Remove from shortlist":"Add to shortlist","membership","secondary",`data-id="${s.id}" ${state.membershipPending?"disabled":""}`)}${button("View evidence","supplier-evidence","tertiary",`data-id="${s.id}"`)}</div><details class="disclosure"><summary>Private notes <span class="save-status" data-status="notes-${s.id}">${dirty("notes-"+s.id)?"Notes not saved":""}</span></summary><div>${input("notes-"+s.id,"notes",`Private notes for ${h(s.name)}`,{area:true})}${footer("notes-"+s.id,"Save notes")}</div></details></article>`).join("")}</div>`}${demoNotice()}`;
}
function evidenceContent(id=state.supplier,field=state.evidenceField){if(state.entry[id]==="manual")return `<h2>Manually entered quote</h2><p>No original PDF or AI extraction exists for this entry. The current values were entered by you.</p>`;const s=suppliers.find(x=>x.id===id), source=sourceQuotes[id], original=source.price;return `<p class="context-label">Original document · synthetic fixture</p><h2>${h(s.name)}</h2><p class="small muted">Quotation · page 1 · ${field==="currency"?"Currency":"Unit price"}</p><div class="paper"><div class="paper-head">${h(s.name.toUpperCase())}</div><p>RECYCLED TRAVEL BAG<br>Reference: SAMPLE-2027-014</p><p>Quantity: ${h(source.quantity)} units</p><mark>Unit price: USD ${original}</mark>${id==="harbor"?`<p class="issue-copy">Intentional fixture conflict: page 2 says EUR; page 1 says USD.</p>`:""}<p>Production: ${h(source.production)}<br>Tooling: ${h(source.currency)} ${h(source.tooling)}<br>Shipping: ${source.shipping?h(source.currency)+" "+h(source.shipping):"Unknown - not provided"}</p><p class="small muted">Synthetic excerpt, not an uploaded PDF.</p></div><div class="evidence-pair"><div><span>AI-extracted price</span><strong>USD ${original}</strong></div><div><span>Saved current price</span><strong>${h(saved[id]?.currency||"Unknown")} ${h(saved[id]?.price||"Unknown")}</strong></div><div><span>Your unsaved price</span><strong>${dirty(id)?h(draft[id].currency)+" "+h(draft[id].price):"No unsaved correction"}</strong></div></div><p class="small muted" style="margin-top:16px">Corrections change the current value. They never rewrite this original evidence.</p>`;}
function quoteAttention(id){const issues=[];if(id==="harbor"&&state.entry[id]!=="manual")issues.push("Currency conflict: source says USD / EUR; unresolved");if(suppliers.find(s=>s.id===id).branding==="Conflict")issues.push("Branding conflict: catalog and quote disagree");if(!saved[id].shipping)issues.push("Shipping cost unknown");if(!saved[id].certifications)issues.push("Certification evidence unknown");return h(issues.length?issues.join(". ")+".":"No material gaps in this fixture.");}
function quoteFields(id){const original=sourceQuotes[id].price,manual=state.entry[id]==="manual";return Object.entries(groups).map(([group,fields])=>`<details class="group" ${["Commercial","Timeline"].includes(group)?"open":""}><summary>${group}<span class="muted">${group==="Compliance"?(saved[id].certifications?"Certification recorded":"Certification unknown"):group==="Terms"?"Optional omissions":group==="Other"?"Conditions and notes":""}</span></summary><div class="fields">${fields.map(([field,label])=>`<div>${input(id,field,label,{numeric:["quantity","price","moq","sample","tooling","shipping"].includes(field),hint:field==="shipping"?(saved[id].shipping?"Saved shipping amount: "+saved[id].currency+" "+saved[id].shipping:"Unknown - no shipping amount was provided."):field==="currency"&&id==="harbor"&&!manual?"Conflict: source says USD on page 1 and EUR on page 2. Unresolved.":undefined})}${field==="price"?`<span class="origin">${manual?"User entered · no document evidence":draft[id].price!==original?"User correction":"AI extracted"} ${manual?"":`· Original: USD ${original}`}</span>`:""}${!manual&&["price","currency"].includes(field)?button("View source evidence ↗","evidence","evidence-trigger",`data-field="${field}" aria-label="View source evidence for ${label}"`):""}</div>`).join("")}</div></details>`).join("");}
function quotes(){
  const common=commonState(); if(common)return heading("Review current values alongside the evidence that supports them.")+common;
  const id=state.supplier,s=suppliers.find(x=>x.id===id),qs=state.quoteStatus[id],unavailable=!state.selected.includes(id);
  return heading("One supplier at a time. Save corrections before confirming.")+`<label class="mobile-supplier">Quote supplier<select id="quote-supplier">${suppliers.map(x=>`<option value="${x.id}" ${x.id===id?"selected":""}>${h(x.name)} - ${state.quoteStatus[x.id]}${dirty(x.id)?" - Unsaved":""}</option>`).join("")}</select></label><div class="supplier-switch" aria-label="Quote supplier">${suppliers.map(x=>button(`${h(x.name)}<small>${state.quoteStatus[x.id]}${dirty(x.id)?" · Unsaved changes":""}</small>`,"supplier","",`data-id="${x.id}" aria-pressed="${x.id===id}"`)).join("")}</div>${unavailable?notice("","This supplier is no longer shortlisted. Your draft is retained for copying or discarding.")+button("Discard unavailable draft","discard","secondary",`data-record="${id}"`):""}${scenario==="failed"?notice("danger","PDF processing failed. The original document is retained.","manual-fallback","Enter manually instead"):""}${conflictNotice(id)}${qs==="Not added"&&!state.entry[id]?`<section class="card"><h2>Add a quote for ${h(s.name)}</h2><p class="muted small">You obtain quotes outside SourcePilot. We do not contact suppliers.</p><div class="two-actions">${button("<strong>Upload PDF</strong><small>Extract values, inspect evidence, then confirm.</small>","upload-choice","choice primary-choice")}${button("<strong>Enter manually</strong><small>Add the information you have. Unknown values are allowed.</small>","manual-choice","choice")}</div></section>`:state.entry[id]==="upload"?`<section class="card"><h2>Upload a supplier quotation</h2><div class="upload-area"><h3>PDF quotation</h3><p class="muted">Prototype: use the synthetic sample. No actual file is read or uploaded.</p>${button("Use sample PDF","sample-upload")}</div>${button("Enter manually instead","manual-choice","tertiary")}</section>`:qs==="Processing"?`<section class="card" role="status"><h2>Processing sample quote…</h2><p>Extraction is simulated. You may review another supplier while this runs.</p>${button("Finish simulated extraction","finish-processing","secondary")}</section>`:`<div class="quote-layout"><div class="quote-fields"><div class="card"><div class="card-head"><div><h2>${h(s.name)}</h2><p>Current quote · ${qs==="Confirmed"?"Human confirmed":"Awaiting human review"}</p></div>${badge(qs)}</div><p class="quote-attention small ${quoteAttention(id).startsWith("No material gaps")?"":"needs-attention"}">${quoteAttention(id)}</p>${qs==="Confirmed"?`<p class="issue-copy">Saving corrections makes the comparison outdated.</p>`:""}</div><fieldset style="border:0;padding:0;margin:0;min-width:0" ${unavailable?"disabled":""}><div class="quote-fields">${quoteFields(id)}</div>${footer(id,qs==="Confirmed"?"Save quote changes":"Save draft",button("Review saved quote","review-quote","secondary",`${dirty(id)||pending[id]||remote[id]||qs==="Not added"?"disabled":""}`))}</fieldset></div><aside class="evidence-panel" aria-label="Quote source evidence">${evidenceContent(id)}</aside></div>`}`;
}
const comparisonRows=()=>{
  const ids=state.comparisonSuppliers, facts=state.comparisonSnapshot;
  const value=(id,field)=>facts[id][field]||"Unknown — not provided";
  const money=(id,field)=>facts[id][field]?`${facts[id].currency||"Unknown currency"} ${facts[id][field]}`:"Unknown — not provided";
  const supplier=id=>suppliers.find(s=>s.id===id);
  return [
    ["Unit price",...ids.map(id=>money(id,"price"))],
    ["Quoted quantity",...ids.map(id=>value(id,"quantity")+(facts[id].quantity==="5000"?" units — differs from request":" units"))],
    ["Minimum order",...ids.map(id=>value(id,"moq"))],
    ["Production lead time",...ids.map(id=>value(id,"production"))],
    ["Tooling cost",...ids.map(id=>money(id,"tooling"))],
    ["Shipping cost",...ids.map(id=>money(id,"shipping"))],
    ["Recycled material · Required",...ids.map(id=>supplier(id).material)],
    ["Custom branding · Required",...ids.map(id=>supplier(id).branding)],
    ["GRS certification · Preferred",...ids.map(id=>supplier(id).certification)]
  ];
};
function comparisonCurrencyConflict(id,label,value){
  return id==="harbor"&&["Unit price","Tooling cost","Shipping cost"].includes(label)&&!value.startsWith("Unknown")
    ? '<p class="issue-copy">Currency conflict: source says USD / EUR; unresolved.</p>' : "";
}
function comparison(){
  const common=commonState();if(common)return heading("Facts first. AI advice supports your judgment.")+common;
  return heading("Compare saved facts, understand gaps and decide what to verify.",state.stale?"Outdated":state.comparison?"Current":"Not generated")+`${state.stale?notice("","These are previous results. Refresh comparison after saving any corrections.","generate","Refresh comparison"):""}${scenario==="failed"?notice("danger","AI analysis could not be verified. The factual comparison remains available.","analyze","Retry analysis"):""}${!state.comparison||scenario==="empty"?`<div class="card empty"><h2>Your confirmed quotes are ready</h2><p>Two confirmed shortlisted quotes are enough. A missing third quote does not block comparison.</p>${button("Generate comparison","generate")}</div>`:`<div class="stack"><div class="notice no-bottom"><strong>Check these differences before comparing price</strong><p>Cedar quotes 5,000 units; your request is for 2,000. Harbor's currency evidence is unresolved (USD / EUR). No currency conversion or clean price ranking is implied.</p></div><div><div class="table-wrap desktop-comparison" role="region" aria-label="Supplier comparison table" tabindex="0"><table><caption class="sr-only">Saved quote and requirement comparison</caption><thead><tr><th scope="col">What matters</th>${state.comparisonSuppliers.map(id=>`<th scope="col">${h(suppliers.find(s=>s.id===id).name)}<br>${badge("Confirmed quote")}</th>`).join("")}</tr></thead><tbody>${comparisonRows().map((r,i)=>`<tr><th scope="row">${r[0]}</th>${r.slice(1).map((v,j)=>`<td>${i===0?`<strong>${h(v)}</strong><span class="origin">${j===0&&state.comparisonSnapshot.harbor.price!=="4.22"?"User corrected · source USD 4.22":"Saved current value"}</span>`:/Unknown|Conflict|Does not meet/.test(v)?badge(v):h(v)}${comparisonCurrencyConflict(state.comparisonSuppliers[j],r[0],v)}${i===0?button("View evidence","comparison-evidence","evidence-trigger",`data-id="${state.comparisonSuppliers[j]}"`):""}</td>`).join("")}</tr>`).join("")}</tbody></table></div><div class="mobile-comparison">${comparisonRows().map((r,i)=>`<section class="card"><h3>${r[0]}</h3>${r.slice(1).map((v,j)=>`<div class="finding"><span class="muted">${h(suppliers.find(s=>s.id===state.comparisonSuppliers[j]).name)}</span><strong>${h(v)}</strong>${comparisonCurrencyConflict(state.comparisonSuppliers[j],r[0],v)}${i===0?button("View evidence","comparison-evidence","evidence-trigger",`data-id="${state.comparisonSuppliers[j]}"`):""}</div>`).join("")}</section>`).join("")}</div><p class="table-caption">${state.comparisonSuppliers.includes("moss")?"Three confirmed quotes are included. Required material failure remains visible.":"Moss has no confirmed quote and is not a comparison column."} No weighted score or automatic winner.</p></div><section class="card advice"><p class="context-label">Optional AI analysis · Simulated</p>${state.aiPending?`<h2>Preparing advice…</h2><p role="status">The facts remain available. No supplier will be selected automatically.</p>`:state.stale?`<h2>Previous advice is outdated</h2><p>Refresh the comparison before requesting new analysis.</p>`:state.ai?`<h2>Harbor is worth investigating first</h2><p class="muted" style="margin-top:10px">Its lower minimum order and shorter lead time fit this request. Verify certification, currency and shipping before choosing.</p><div class="grid-two" style="margin-top:18px"><div><h3>Important unknowns</h3><p class="small">Harbor: certification evidence and shipping cost.</p></div><div><h3>Important conflicts</h3><p class="small">Harbor: currency evidence. Cedar: branding descriptions.</p></div></div>`:`<h2>No supplier suggested yet</h2><p>Insufficient evidence is a valid outcome. You may still record your own preference.</p>`}<div class="actions" style="margin-top:20px">${button("Analyze comparison","analyze","secondary",`${state.stale||state.aiPending?"disabled":""}`)}${button("Record your preference →","go-decision","tertiary")}</div></section></div>`}`;
}
function decision(){
  return heading("Your saved preference is separate from any AI suggestion.")+`${scenario==="loading"?loading():`${state.stale?notice("","The comparison is outdated. You can still manage your preference.","go-comparison","Review comparison"):""}<div class="stack"><section class="selected-preference"><p class="context-label">Saved human preference</p><h2>${state.preference?h(suppliers.find(s=>s.id===state.preference).name):"No preference saved yet"}</h2><p class="small">Recording a preference does not place an order or contact a supplier.</p>${state.preference&&!state.selected.includes(state.preference)?`<p class="issue-copy">Your saved supplier is no longer shortlisted. Notes and clearing remain available.</p>`:""}</section><section class="card"><div class="card-head"><div><h2>Choose a shortlisted supplier</h2><p>You may choose before comparison, disagree with AI, or change your mind later.</p></div></div><div class="notice info"><strong>AI suggestion: Harbor Pouch Works</strong><p>Advisory only. This is not your saved preference.</p></div><label>Proposed preference <span class="muted">Not saved until you confirm</span><select data-record="decision" data-field="selection"><option value="">Choose a supplier</option>${suppliers.filter(s=>state.selected.includes(s.id)).map(s=>`<option value="${s.id}" ${draft.decision.selection===s.id?"selected":""}>${h(s.name)}</option>`).join("")}</select></label><div style="margin-top:18px">${input("decision","notes","Decision notes (optional)",{area:true,hint:"Record your reasoning or what still needs verification."})}</div>${conflictNotice("decision")}<div class="record-footer"><span data-status="decision" class="save-status">${status("decision")}</span><div class="actions">${button("Mark as preferred supplier","review-decision")}${button("Save decision notes","save-notes","secondary")}${state.preference?button("Clear preference","clear-preference","tertiary"):""}</div></div></section></div>`}`;
}
function render(focus=false){
  const focused=document.activeElement;
  const restore=app.contains(focused)?{action:focused.dataset.action,id:focused.dataset.id,record:focused.dataset.record,field:focused.dataset.field,requirement:focused.dataset.requirement,part:focused.dataset.part,start:focused.selectionStart,end:focused.selectionEnd,elementId:focused.id}:null;
  const disclosureKey=(el,v,s)=>`${v}:${v==="quotes"?s:""}:${el.querySelector('summary')?.firstChild?.textContent.trim()}:${el.querySelector('[data-record]')?.dataset.record||""}`;
  app.querySelectorAll('details').forEach(el=>disclosures.set(disclosureKey(el,renderedView,renderedSupplier),el.open));
  const n=next(),content=view==="dashboard"?dashboard():({brief,suppliers:supplierView,quotes,comparison,decision}[view])();
  app.innerHTML=`<header class="topbar"><a href="?stage=dashboard" data-nav="dashboard" class="brand" style="text-decoration:none;color:var(--ink)"><span class="brand-mark" aria-hidden="true">SP</span>SourcePilot</a><span class="tag">Evidence for better sourcing decisions</span>${view!=="dashboard"?button("← All projects","leave","tertiary"):""}</header>${view==="dashboard"?`<main class="dashboard" id="content">${content}</main>`:`<div class="workspace"><aside class="rail"><p class="context-label" style="padding-left:12px">Your sourcing workflow</p><nav aria-label="Sourcing stages">${stages.map((s,i)=>`<a href="?stage=${s}" data-nav="${s}" ${view===s?'aria-current="page"':""}><span class="step">${i+1}</span><span class="stage-label">${title(s)}${n[0]===s?"<small>Needs attention</small>":""}<small data-stage-dirty="${s}"></small></span>${n[0]===s?'<span class="dot" aria-hidden="true"></span>':""}</a>`).join("")}</nav><p class="rail-note">A saved preference never hides upstream work that needs attention.</p></aside><main class="main" id="content"><div class="context"><div><p class="context-label">Project workspace</p><span class="project-name">${h(saved.project.name)}</span> ${button("Rename","rename","tertiary")}</div><div class="preference">Saved preference<br><strong>${state.preference?h(suppliers.find(s=>s.id===state.preference).name):"No decision yet"}</strong></div></div><div class="next-action"><div><p class="context-label" style="margin-bottom:3px">Needs attention · ${title(n[0])}</p><p>${n[1]}</p></div>${button(n[2],"next","secondary")}</div>${state.feedback?`<p role="status" class="notice info">${h(state.feedback)}</p>`:""}${content}<p class="page-foot">Synthetic design study · Every save and approval on this page is simulated.</p></main></div>`}`;
  app.querySelectorAll('details').forEach(el=>{const key=disclosureKey(el,view,state.supplier);if(disclosures.has(key))el.open=disclosures.get(key);});
  renderedView=view;renderedSupplier=state.supplier;
  document.title=`${title(view)} · SourcePilot design prototype`;
  document.getElementById("scenario").value=scenario;
  updateStatus(); if(focus){document.getElementById("stage-title")?.focus();window.scrollTo(0,0);}
  else if(restore){let target=restore.elementId?document.getElementById(restore.elementId):restore.field?[...app.querySelectorAll('[data-field]')].find(el=>el.dataset.field===restore.field&&el.dataset.record===restore.record):restore.requirement?[...app.querySelectorAll('[data-requirement]')].find(el=>el.dataset.requirement===restore.requirement&&el.dataset.part===restore.part):restore.action?[...app.querySelectorAll('[data-action]')].find(el=>el.dataset.action===restore.action&&el.dataset.id===restore.id&&el.dataset.record===restore.record):null;if(target?.disabled&&restore.record){target=app.querySelector(`[data-status="${restore.record}"]`);if(target)target.tabIndex=-1;}if(target){target.focus({preventScroll:true});if(restore.start!==null&&restore.start!==undefined&&target.setSelectionRange)target.setSelectionRange(restore.start,restore.end);}}
}
function updateStatus(){document.querySelectorAll('[data-action="save"][data-record="brief"]').forEach(b=>{b.disabled=!dirty("brief")||!!pending.brief||!!remote.brief;b.classList.toggle("secondary",!dirty("brief"));});document.querySelectorAll("[data-status]").forEach(el=>{const key=el.dataset.status;el.textContent=key.startsWith("notes-")&&dirty(key)?"Notes not saved":status(key);el.dataset.dirty=dirty(key);});document.querySelectorAll('[data-action="review-brief"],[data-action="review-quote"]').forEach(b=>{const key=b.dataset.action==="review-brief"?"brief":state.supplier;b.disabled=dirty(key)||!!pending[key]||!!remote[key]||(b.dataset.action==="review-quote"&&state.quoteStatus[key]==="Not added");});document.querySelectorAll("[data-stage-dirty]").forEach(el=>{const s=el.dataset.stageDirty;const has=s==="brief"?dirty("brief"):s==="quotes"?suppliers.some(x=>dirty(x.id)):s==="suppliers"?suppliers.some(x=>dirty("notes-"+x.id)):s==="decision"?dirty("decision"):false;el.textContent=has?"Unsaved changes":"";});}
function navigate(target,replace=false,departureAuthorized=false){if(!departureAuthorized&&target==="dashboard"&&view!=="dashboard"&&(dirtyKeys().length||Object.keys(pending).length))return leaveDialog(); view=target;const url=new URL(location.href);url.searchParams.set("stage",target);url.hash="";history[replace?"replaceState":"pushState"]({stage:target},"",url);render(true);}
function resolveLocation(){const url=new URL(location.href), values=url.searchParams.getAll("stage"),legacy={"shortlist-review":"suppliers","shortlist-approve":"suppliers","brief-approve":"brief","brief-complete":"brief","quotes-review":"quotes","comparison-generate":"comparison","decision-choice":"decision"};const hash=url.hash.slice(1),valid=values.length===1&&["dashboard",...stages].includes(values[0]);view=valid?values[0]:legacy[hash]||(stages.includes(hash)?hash:values.length?next()[0]:"dashboard");url.searchParams.set("stage",view);if(!valid||hash){url.hash="";history.replaceState({stage:view},"",url);}}
function openModal(titleText,body,actions,sheet=false){lastFocus=document.activeElement;modal.className=sheet?"sheet":"";modal.innerHTML=`<div class="modal-body"><div class="modal-heading"><h2 id="modal-title" tabindex="-1">${titleText}</h2>${button("Close","close","tertiary",`aria-label="Close dialog"`)}</div>${body}<div class="modal-actions">${actions}</div></div>`;if(!modal.open)modal.showModal();modal.querySelector('[data-action="close"]')?.focus();}
function closeModal(){modal.close();clearTimeout(departureTimer);state.departure=false;lastFocus?.isConnected&&lastFocus.focus();}
function requestCloseModal(){
  if(modal.querySelector('[data-record="project"][data-field="name"]')&&dirty("project")){
    openModal("Discard the unsaved project name?","<p>The project still uses its saved name. Keep editing or explicitly discard this rename.</p>",button("Keep editing","rename","secondary")+button("Discard name edit","discard-now","danger",'data-record="project"'));return;
  }
  closeModal();
}
function save(key,snapshot=clone(draft[key]),options={}){
  if(pending[key]||remote[key])return;
  pending[key]=true;delete errors[key];announce(`Saving ${key} in the simulation.`);render();
  const gen=generation,chosenMode=mode,delay=chosenMode==="pending"?20000:700;
  setTimeout(()=>{if(gen!==generation)return;delete pending[key];if(chosenMode==="failed"){errors[key]="Save failed. Your draft is retained.";announce(errors[key]);}else{
    const before=clone(saved[key]);const cleanBeforeResponse=!dirty(key);saved[key]=snapshot;
    if(cleanBeforeResponse)draft[key]=clone(snapshot);
    if(key==="decision"){
      if(options.notesOnly){saved.decision.selection=before.selection;}
      else {state.preference=snapshot.selection||null;}
    }
    if(key==="brief"){state.suppliersStale=true;state.stale=true;if(!snapshot.destination||!snapshot.product||!snapshot.quantity)state.briefApproved=false;}
    if(suppliers.some(s=>s.id===key)){if(["Not added","Failed"].includes(state.quoteStatus[key]))state.quoteStatus[key]="Needs review";if(state.quoteStatus[key]==="Confirmed")state.stale=true;}
    announce(dirty(key)?"Submitted values saved. Newer edits remain unsaved.":"Changes saved in the simulation.");
  }render();if(state.departure&&modal.open)leaveDialog(true);},delay);
}
function leaveDialog(update=false){state.departure=true;const hasPending=Object.keys(pending).length>0;const records=[...new Set([...dirtyKeys(),...Object.keys(pending)])];openModal(hasPending?"Leave while a save is unconfirmed?":"Leave with unsaved changes?",`<p>${hasPending?"Leaving does not cancel a request already submitted. On return, SourcePilot reloads saved data; unsaved drafts may be lost.":"Your unsaved edits will be discarded when you leave this project."}</p><ul class="callout-list">${records.map(k=>`<li>${h(k==="brief"?"Brief":k==="decision"?"Decision":k==="project"?"Project name":recordLabel(k))}</li>`).join("")}</ul><p id="departure-status" role="status">${hasPending?"Save still in progress. You can leave now or stay.":"Save each record separately if you want to keep these changes."}</p>`,button("Stay","close","secondary")+button(hasPending?"Leave anyway":"Discard unsaved changes and leave","leave-now","danger"));state.departure=true;
  if(hasPending&&!update)departureTimer=setTimeout(()=>{if(modal.open&&state.departure){document.getElementById("departure-status").textContent="Save outcome not yet confirmed. Check saved state or leave; this does not cancel processing.";modal.querySelector(".modal-actions").insertAdjacentHTML("beforeend",button("Check saved state","check-state","secondary"));}},10000);
}
function conflict(key){const latest=remote[key];if(!latest)return;openModal("Review the complete record",`<p>Nothing has been merged. Related values must be reviewed together. Choosing your draft does not save it.</p><div class="conflict-grid"><div><h3>Latest saved record</h3>${recordSummary(key,latest)}</div><div><h3>Your unsaved draft</h3>${recordSummary(key,draft[key])}</div></div>`,button("Keep reviewing","close","secondary")+button("Use saved record","use-remote","secondary",`data-record="${key}"`)+button("Review my complete draft","review-local","",`data-record="${key}"`));}
function simulateExternal(){const key=view==="quotes"?state.supplier:view==="suppliers"?"notes-harbor":view==="decision"?"decision":"brief";const latest=clone(saved[key]);if(key==="brief"){latest.destination="Melbourne, Australia";latest.requirements=latest.requirements.filter(r=>r.id!=="material");latest.requirements.push({id:"external-packaging",kind:"Packaging",value:"Plastic-free",importance:"Required"});}else if(key.startsWith("notes-"))latest.notes="Externally saved private note";else if(key==="decision")latest.notes="A colleague updated the saved reasoning";else{latest.currency="EUR";latest.price="4.60";}if(dirty(key)){remote[key]=latest;render();announce("Saved values changed. Your complete draft is preserved for review.");}else{saved[key]=latest;draft[key]=clone(latest);render();announce("Clean record refreshed from simulated saved data.");}}
function applyScenario(value){scenario=value;state.feedback="";if(value==="three"){saved.moss=clone(sourceQuotes.moss);draft.moss=clone(saved.moss);state.quoteStatus.moss="Confirmed";state.comparisonSnapshot=clone(saved);state.comparisonSuppliers=["harbor","cedar","moss"];}if(value==="stale"){state.stale=true;state.suppliersStale=true;}if(value==="review"){state.briefApproved=false;state.shortlistApproved=false;state.quoteStatus.harbor="Needs review";state.comparison=false;}if(value==="blocked"){state.briefApproved=false;state.shortlistApproved=false;if(view==="brief"){saved.brief.destination="";draft.brief.destination="";}}if(value==="empty"&&view==="quotes"){state.supplier="moss";state.entry.moss=null;}render();}
document.addEventListener("input",event=>{const el=event.target;if(el.dataset.record&&el.dataset.field){draft[el.dataset.record][el.dataset.field]=el.value;delete errors[el.dataset.record];updateStatus();}if(el.dataset.requirement){const r=draft.brief.requirements.find(x=>x.id===el.dataset.requirement);r[el.dataset.part]=el.value;updateStatus();}});
document.addEventListener("change",event=>{const el=event.target;if(el.id==="quote-supplier"){state.supplier=el.value;render();document.getElementById("quote-supplier")?.focus({preventScroll:true});}if(el.id==="scenario")applyScenario(el.value);if(el.id==="save-mode")mode=el.value;});
document.addEventListener("submit",e=>e.preventDefault());
document.getElementById("external").addEventListener("click",simulateExternal);
document.getElementById("reset").addEventListener("click",()=>{reset();scenario="normal";render();announce("Simulation reset. No application data changed.");});
document.addEventListener("click",event=>{
  const link=event.target.closest("[data-nav]");if(link){event.preventDefault();navigate(link.dataset.nav);return;}
  const el=event.target.closest("[data-action]");if(!el||el.disabled)return;const action=el.dataset.action,key=el.dataset.record,id=el.dataset.id;
  if(action==="close")return requestCloseModal();
  if(action==="edit-brief"){state.briefEditing=true;render();app.querySelector('[data-record="brief"][data-field="product"]')?.focus();return;}
  if(action==="save")return save(key);
  if(action==="discard")return openModal("Discard this record's unsaved edits?","<p>Use the latest known saved values for this record. Other drafts remain untouched.</p>",button("Keep editing","close","secondary")+button("Discard this draft","discard-now","danger",`data-record="${key}"`));
  if(action==="discard-now"){saved[key]=remote[key]||saved[key];draft[key]=clone(saved[key]);delete remote[key];delete errors[key];closeModal();render();return;}
  if(action==="leave")return dirtyKeys().length||Object.keys(pending).length?leaveDialog():navigate("dashboard");
  if(action==="leave-now"){draft=clone(saved);remote={};errors={};closeModal();navigate("dashboard",false,true);return;}
  if(action==="check-state"){document.getElementById("departure-status").textContent=Object.keys(pending).length?"The last saved values are available, but this pending save is still unconfirmed. You can check again or leave.":"The simulated request has settled. Leaving will discard any remaining unsaved edits.";return;}
  if(action==="open-project")return navigate("brief");
  if(action==="next")return navigate(next()[0]);
  if(action.startsWith("go-"))return navigate(action.slice(3));
  if(action==="supplier"){state.supplier=id;render(true);announce(`Viewing ${suppliers.find(s=>s.id===id).name}. Other quote drafts retained.`);return;}
  if(action==="recover"){scenario="normal";render();return;}
  if(action==="create")return openModal("Create a sourcing project",`<label>Project name<input id="new-name" value="Recycled travel bags"></label><label style="margin-top:16px">What do you want to source?<textarea id="new-request">2,000 recycled travel bags with our logo, delivered to Sydney.</textarea></label><p class="small muted" style="margin-top:12px">Simulated creation only. No project will be added to the application.</p>`,button("Cancel","close","secondary")+button("Create sample project","create-now"));
  if(action==="create-now"){saved.project.name=document.getElementById("new-name").value||"Untitled sample";draft.project=clone(saved.project);closeModal();scenario="review";state.briefApproved=false;navigate("brief");return;}
  if(action==="rename")return openModal("Rename project",input("project","name","Project name"),button("Close","close","secondary")+button("Save name","rename-save"));
  if(action==="rename-save"){save("project");closeModal();return;}
  if(action==="add-requirement"){draft.brief.requirements.push({id:`local-${Date.now()}`,kind:"Additional requirement",value:"",importance:"Preferred"});render();return;}
  if(action==="remove-requirement"){draft.brief.requirements=draft.brief.requirements.filter(r=>r.id!==id);render();return;}
  if(action==="review-brief")return openModal("Review saved Brief before approval",`<p>This review contains saved values only.</p>${recordSummary("brief",saved.brief)}<p class="issue-copy">Target currency is unknown; the target price has no confirmed currency. Optional omissions are shown as Not provided and do not block approval.</p>${!saved.brief.destination||!saved.brief.product||!saved.brief.quantity?'<p class="issue-copy">Product, quantity and destination must be provided before approval.</p>':""}<details class="disclosure"><summary>Original request</summary><p>We need 2,000 recycled cosmetic travel bags with our logo. Target below $5 each, delivered to Sydney in November. Prefer GRS certification.</p></details>`,button("Continue editing","close","secondary")+button(state.briefApproved?"Brief already approved":"Approve Brief","approve-brief","",state.briefApproved||!saved.brief.destination||!saved.brief.product||!saved.brief.quantity?"disabled":""));
  if(action==="approve-brief"){state.briefApproved=true;closeModal();state.feedback="Brief approved in the simulation. You are still viewing Brief.";render();return;}
  if(action==="review-shortlist")return openModal("Review your saved shortlist",`<p>${state.selected.length} selected. Private-note drafts are preserved and are not part of this approval.</p>${suppliers.filter(s=>state.selected.includes(s.id)).map(s=>`<section style="margin-top:20px"><h3>${h(s.name)}</h3>${supplierFindings(s)}</section>`).join("")}<p class="small muted">Required failures and unknowns remain visible; they do not silently remove a supplier.</p>`,button("Continue reviewing","close","secondary")+button("Approve shortlist","approve-shortlist","",!state.briefApproved||!state.selected.length||state.membershipPending?"disabled":""));
  if(action==="approve-shortlist"){state.shortlistApproved=true;closeModal();state.feedback="Shortlist approved. Any private-note drafts are still unsaved.";render();return;}
  if(action==="membership"){if(state.selected.includes(id)&&(dirty(id)||dirty("notes-"+id)))return openModal("Remove a supplier with unsaved edits?","<p>The quote and private-note drafts will be discarded only after a successful removal. Cancel to keep reviewing.</p>",button("Cancel removal","close","secondary")+button("Discard edits and remove","remove-supplier","danger",`data-id="${id}"`));if(state.selected.includes(id)){state.selected=state.selected.filter(x=>x!==id);}else state.selected.push(id);state.shortlistApproved=false;state.stale=true;render();return;}
  if(action==="remove-supplier"){if(pending[id]||pending["notes-"+id])return leaveDialog();state.selected=state.selected.filter(x=>x!==id);draft[id]=clone(saved[id]);draft["notes-"+id]=clone(saved["notes-"+id]);state.shortlistApproved=false;state.stale=true;closeModal();render();return;}
  if(action==="supplier-evidence")return openModal("Supplier evidence",`<p class="context-label">Curated synthetic source</p><h3>${h(suppliers.find(s=>s.id===id).name)}</h3><div class="paper">${id==="moss"?"Material declaration: virgin polyester. This does not meet recycled-material requirements.":id==="cedar"?"Catalog: printed logos supported. Quote: only blank pouches supplied. These sources conflict.":"Material declaration: recycled polyester supported. No GRS certificate was supplied; certification is unknown."}</div><p>Unknown means insufficient evidence. Conflict means evidence disagrees.</p>`,button("Back to supplier","close","secondary"));
  if(action==="refresh-suppliers"){state.suppliersStale=false;scenario="normal";render();return;}
  if(action==="manual-choice"||action==="manual-fallback"){state.entry[state.supplier]="manual";scenario="normal";render();return;}
  if(action==="upload-choice"){state.entry[state.supplier]="upload";render();return;}
  if(action==="sample-upload"){state.entry[state.supplier]="pdf";state.quoteStatus[state.supplier]="Processing";render();return;}
  if(action==="finish-processing"){saved[state.supplier]=clone(sourceQuotes[state.supplier]);draft[state.supplier]=clone(saved[state.supplier]);state.quoteStatus[state.supplier]="Needs review";render();return;}
  if(action==="evidence"||action==="comparison-evidence"){const supplier=id||state.supplier;state.evidenceField=el.dataset.field||"price";return openModal("Quote source evidence",evidenceContent(supplier,state.evidenceField),button("Back to quote field","close","secondary"),innerWidth<1280);}
  if(action==="review-quote"){const q=saved[state.supplier];return openModal("Review saved quote",`<p>For ${h(suppliers.find(s=>s.id===state.supplier).name)}. This is saved information, not an unsaved draft.</p><div class="review-summary">${Object.values(groups).flat().map(([field,label])=>`<div><span>${label}</span><strong>${h(q[field]||"Unknown — not provided")}</strong></div>`).join("")}</div><p class="issue-copy">${state.entry[state.supplier]==="manual"?"Manually entered values have no original PDF evidence.":`Original source price remains ${h(sourceQuotes[state.supplier].currency)} ${h(sourceQuotes[state.supplier].price)}. A correction is a human-entered current value.`}</p>`,button("Back to correction","close","secondary")+button(state.quoteStatus[state.supplier]==="Confirmed"?"Already confirmed":"Confirm quote","confirm-quote","",state.quoteStatus[state.supplier]==="Confirmed"?"disabled":""));}
  if(action==="confirm-quote"){state.quoteStatus[state.supplier]="Confirmed";state.stale=true;closeModal();render();return;}
  if(action==="generate"){state.comparisonSnapshot=clone(saved);state.comparisonSuppliers=state.selected.filter(id=>state.quoteStatus[id]==="Confirmed");state.comparison=true;state.stale=false;state.ai=false;scenario="normal";render();announce("Comparison refreshed using saved values. Analysis is optional.");return;}
  if(action==="analyze"){state.aiPending=true;render();const gen=generation;setTimeout(()=>{if(gen!==generation)return;state.aiPending=false;state.ai=true;scenario="normal";render();announce("Simulated advisory analysis ready. No human preference changed.");},900);return;}
  if(action==="review-decision"){if(!draft.decision.selection)return announce("Choose a shortlisted supplier first.");return openModal("Save this human preference?",`<p><strong>${h(suppliers.find(s=>s.id===draft.decision.selection).name)}</strong></p><p>${h(draft.decision.notes||"No decision notes entered.")}</p><p>This explicitly saves your choice and these notes together. It does not place an order.</p>`,button("Keep reviewing","close","secondary")+button("Save preferred supplier","confirm-decision"));}
  if(action==="confirm-decision"){closeModal();save("decision");return;}
  if(action==="save-notes"){save("decision",{selection:saved.decision.selection,notes:draft.decision.notes},{notesOnly:true});return;}
  if(action==="clear-preference")return openModal("Clear saved preference?","<p>Saved notes remain. Any draft replacement or unsaved notes stay in the editor.</p>",button("Keep preference","close","secondary")+button("Clear preference","clear-now","danger"));
  if(action==="clear-now"){state.preference=null;saved.decision.selection="";closeModal();render();return;}
  if(action==="conflict")return conflict(key);
  if(action==="use-remote"){saved[key]=clone(remote[key]);draft[key]=clone(remote[key]);delete remote[key];closeModal();render();return;}
  if(action==="review-local")return openModal("Confirm the complete draft you intend to keep",`<p>Review every value, including currency and the whole requirement list. This replaces the editor baseline only; you must still save explicitly. Removed requirements are not silently recreated.</p>${recordSummary(key,draft[key])}`,button("Back to conflict","conflict","secondary",`data-record="${key}"`)+button("Keep this draft for editing","keep-local","",`data-record="${key}"`));
  if(action==="keep-local"){
    if(key==="brief"&&JSON.stringify(saved.brief.requirements.map(r=>r.id).sort())!==JSON.stringify(remote.brief.requirements.map(r=>r.id).sort())){
      openModal("Requirement membership changed",`<p>The saved record added or removed requirements. A complete draft replacement could restore deleted requirements or remove new ones.</p><p>Use the saved record, then deliberately add or edit requirements using the normal editor. Your previous draft remains here to copy before choosing.</p>${recordSummary("brief",draft.brief)}`,button("Keep reviewing","close","secondary")+button("Use saved record","use-remote","",`data-record="brief"`));return;
    }
    saved[key]=clone(remote[key]);delete remote[key];closeModal();render();announce("Draft retained after explicit review. It has not been saved.");return;
  }
});
window.addEventListener("beforeunload",e=>{if(dirtyKeys().length||Object.keys(pending).length){e.preventDefault();e.returnValue="";}});
window.addEventListener("popstate",()=>{const target=new URL(location.href).searchParams.get("stage");if(target==="dashboard"&&view!=="dashboard"&&(dirtyKeys().length||Object.keys(pending).length)){const url=new URL(location.href);url.searchParams.set("stage",view);history.pushState({stage:view},"",url);leaveDialog();}else{resolveLocation();render(true);}});
modal.addEventListener("close",()=>{clearTimeout(departureTimer);state.departure=false;});
modal.addEventListener("cancel",event=>{if(modal.querySelector('[data-record="project"][data-field="name"]')&&dirty("project")){event.preventDefault();requestCloseModal();}});
modal.addEventListener("keydown",event=>{if(event.key!=="Tab")return;const targets=[...modal.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href],[tabindex="0"]')].filter(el=>el.getClientRects().length);const first=targets[0],last=targets.at(-1);if(!first)return;if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});
reset();const initial=new URL(location.href);scenario=initial.searchParams.get("scenario")||"normal";view=initial.searchParams.get("stage")||"dashboard";resolveLocation();applyScenario(scenario);
